/**
 * Date & Time Utilities
 */

/**
 * Get start of month (00:00:00)
 */
export function getStartOfMonth(date: Date = new Date()): Date {
  const result = new Date(date)
  result.setDate(1)
  result.setHours(0, 0, 0, 0)
  return result
}

/**
 * Get end of month (23:59:59)
 */
export function getEndOfMonth(date: Date = new Date()): Date {
  const result = new Date(date.getFullYear(), date.getMonth() + 1, 0)
  result.setHours(23, 59, 59, 999)
  return result
}

/**
 * Get start of day (00:00:00)
 */
export function getStartOfDay(date: Date = new Date()): Date {
  const result = new Date(date)
  result.setHours(0, 0, 0, 0)
  return result
}

/**
 * Get end of day (23:59:59)
 */
export function getEndOfDay(date: Date = new Date()): Date {
  const result = new Date(date)
  result.setHours(23, 59, 59, 999)
  return result
}

/**
 * Get start of year
 */
export function getStartOfYear(date: Date = new Date()): Date {
  const result = new Date(date.getFullYear(), 0, 1)
  result.setHours(0, 0, 0, 0)
  return result
}

/**
 * Format date untuk display (Indonesia)
 */
export function formatDate(date: Date = new Date(), locale: string = 'id-ID'): string {
  return date.toLocaleDateString(locale, {
    day: '2-digit',
    month: 'short',
    year: 'numeric',
  })
}

/**
 * Format tanggal dan waktu
 */
export function formatDateTime(date: Date = new Date(), locale: string = 'id-ID'): string {
  return date.toLocaleString(locale, {
    day: '2-digit',
    month: 'short',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  })
}

/**
 * Format hanya waktu
 */
export function formatTime(date: Date = new Date()): string {
  return date.toLocaleTimeString('id-ID', {
    hour: '2-digit',
    minute: '2-digit',
  })
}

/**
 * Get days between dua date
 */
export function daysBetween(startDate: Date, endDate: Date): number {
  const msPerDay = 24 * 60 * 60 * 1000
  return Math.floor((endDate.getTime() - startDate.getTime()) / msPerDay)
}

/**
 * Subtract days dari date
 */
export function subtractDays(date: Date, days: number): Date {
  const result = new Date(date)
  result.setDate(result.getDate() - days)
  return result
}

/**
 * Add days ke date
 */
export function addDays(date: Date, days: number): Date {
  const result = new Date(date)
  result.setDate(result.getDate() + days)
  return result
}

/**
 * Format untuk URL param (YYYY-MM-DD)
 */
export function formatDateForParam(date: Date = new Date()): string {
  const year = date.getFullYear()
  const month = String(date.getMonth() + 1).padStart(2, '0')
  const day = String(date.getDate()).padStart(2, '0')
  return `${year}-${month}-${day}`
}

/**
 * Parse date string (YYYY-MM-DD)
 */
export function parseDate(dateString: string): Date {
  const [year, month, day] = dateString.split('-').map(Number)
  return new Date(year, month - 1, day)
}

/**
 * Get bulan dalam bahasa Indonesia
 */
export const BULAN = [
  'Januari',
  'Februari',
  'Maret',
  'April',
  'Mei',
  'Juni',
  'Juli',
  'Agustus',
  'September',
  'Oktober',
  'November',
  'Desember',
]

/**
 * Get bulan pendek dalam bahasa Indonesia
 */
export const BULAN_PENDEK = ['Jan', 'Feb', 'Mar', 'Apr', 'Mei', 'Jun', 'Jul', 'Agu', 'Sep', 'Okt', 'Nov', 'Des']

/**
 * Format bulan-tahun
 */
export function formatMonthYear(date: Date = new Date(), short: boolean = false): string {
  const month = short ? BULAN_PENDEK[date.getMonth()] : BULAN[date.getMonth()]
  return `${month} ${date.getFullYear()}`
}
