"use client";

import { useState, useEffect, useMemo } from "react";
import {
  Box,
  Button,
  Chip,
  FormControl,
  InputLabel,
  MenuItem,
  Paper,
  Select,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Typography,
  Divider,
} from "@mui/material";
import {
  ArrowDownward,
  ArrowUpward,
  Download,
  SwapVert,
  CreditCard,
} from "@mui/icons-material";
import { exportToPDF } from "@/lib/report-pdf";
import { getLiabilityReportAction } from "@/features/liability/actions";
import type { LiabilityRow } from "@/types/report.type";
import { LIABILITY_CATEGORY_LABELS } from "@/features/liability/types/liability.type";
import type { LiabilityCategory } from "@/features/liability/types/liability.type";
import { BULAN as indonesianMonths } from "@/lib/date";

// ─── Helpers ─────────────────────────────────────────────────────────────────
const formatIDR = (n: number) =>
  new Intl.NumberFormat("id-ID", { style: "currency", currency: "IDR", maximumFractionDigits: 0 }).format(n);

const cellSx = {
  borderColor: "rgba(255,255,255,0.05)",
  color: "#cbd5e1",
  fontSize: "0.8125rem",
  py: 1.5,
};

const headCellSx = {
  borderColor: "rgba(255,255,255,0.05)",
  backgroundColor: "#0b1829",
  color: "#64748b",
  fontSize: "0.6875rem",
  fontWeight: 700,
  letterSpacing: "0.06em",
  textTransform: "uppercase" as const,
  py: 1.5,
  whiteSpace: "nowrap" as const,
};

export default function LiabilityReportPage() {
  const [selectedMonth, setSelectedMonth] = useState("");
  const [months, setMonths] = useState<string[]>([]);
  const [allRows, setAllRows] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function fetchReport() {
      try {
        const res = await getLiabilityReportAction();
        if (res.success && res.data) {
          const reportRows = res.data as LiabilityRow[];
          setAllRows(reportRows);

          // Get unique months from ledger dates
          const uniquePeriods = Array.from(
            new Set(
              reportRows.map((row) => {
                const date = new Date(row.tanggal);
                return `${indonesianMonths[date.getMonth()]} ${date.getFullYear()}`;
              })
            )
          );

          // Always ensure the current month is an option even if empty
          const now = new Date();
          const currentPeriod = `${indonesianMonths[now.getMonth()]} ${now.getFullYear()}`;
          if (!uniquePeriods.includes(currentPeriod)) {
            uniquePeriods.push(currentPeriod);
          }

          setMonths(uniquePeriods);
          
          if (uniquePeriods.length > 0) {
            setSelectedMonth(currentPeriod);
          }
        }
      } catch (err) {
        console.error("Failed to fetch liability report", err);
      } finally {
        setLoading(false);
      }
    }
    fetchReport();
  }, []);

  // Filter rows by selected month
  const rows = useMemo(() => {
    return allRows.filter((row) => {
      if (!selectedMonth) return true;
      const date = new Date(row.tanggal);
      const rowPeriod = `${indonesianMonths[date.getMonth()]} ${date.getFullYear()}`;
      return rowPeriod === selectedMonth;
    });
  }, [allRows, selectedMonth]);

  const totalPembayaran = useMemo(() =>
    rows.filter((r) => r.tipe === "Pembayaran").reduce((s, r) => s + r.nominal, 0),
  [rows]);

  const totalBungaPenambahan = useMemo(() =>
    rows.filter((r) => r.tipe === "Bunga").reduce((s, r) => s + r.nominal, 0),
  [rows]);

  const netReduction = totalPembayaran - totalBungaPenambahan;
  const finalOutstanding = rows[0]?.saldoOutstanding ?? 0;

  const handleExportPDF = () => {
    const headers = ["Tanggal", "Keterangan", "Tipe", "Kategori", "Akun Liabilitas", "Nominal", "Sisa Outstanding"];
    const pdfRows = rows.map((row) => [
      new Date(row.tanggal).toLocaleDateString("id-ID", { day: "2-digit", month: "short", year: "numeric" }),
      row.keterangan,
      row.tipe,
      LIABILITY_CATEGORY_LABELS[row.kategori as LiabilityCategory] || row.kategori,
      row.metode,
      `${row.tipe === "Bunga" ? "+" : "-"}${formatIDR(row.nominal)}`,
      formatIDR(row.saldoOutstanding)
    ]);

    const meta = [
      { label: "Periode", value: selectedMonth },
      { label: "Total Pembayaran", value: formatIDR(totalPembayaran) },
      { label: "Total Bunga", value: formatIDR(totalBungaPenambahan) },
      { label: "Penurunan Bersih Hutang", value: formatIDR(netReduction) },
      { label: "Sisa Outstanding Akhir", value: formatIDR(finalOutstanding) }
    ];

    exportToPDF(
      "Liability Financial Report",
      headers,
      pdfRows,
      `Liability_Report_${selectedMonth.replace(" ", "_")}.pdf`,
      meta
    );
  };

  return (
    <Box sx={{ p: { xs: 3, md: 4 }, minHeight: "100vh" }}>
      {/* ── Header ─────────────────────────────────────────────────────── */}
      <Box sx={{ mb: 4, display: "flex", alignItems: "flex-start", justifyContent: "space-between", flexWrap: "wrap", gap: 2 }}>
        <Box>
          <Box sx={{ display: "flex", alignItems: "center", gap: 1.5, mb: 0.5 }}>
            <Box
              sx={{
                width: 36,
                height: 36,
                borderRadius: "10px",
                backgroundColor: "rgba(248,113,113,0.15)",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
              }}
            >
              <CreditCard sx={{ fontSize: 18, color: "#f87171" }} />
            </Box>
            <Typography variant="h5" sx={{ fontWeight: 700, color: "#f1f5f9", fontSize: "1.25rem" }}>
              Laporan Liabilitas
            </Typography>
          </Box>
          <Typography variant="body2" sx={{ color: "#64748b", ml: "52px" }}>
            Laporan pelunasan hutang, beban bunga, dan perkembangan sisa cicilan
          </Typography>
        </Box>

        <Box sx={{ display: "flex", alignItems: "center", gap: 1.5 }}>
          <FormControl size="small" sx={{ minWidth: 160 }}>
            <InputLabel
              sx={{ color: "#64748b", fontSize: "0.8125rem", "&.Mui-focused": { color: "#818cf8" } }}
            >
              Periode
            </InputLabel>
            <Select
              value={selectedMonth}
              label="Periode"
              onChange={(e) => setSelectedMonth(e.target.value)}
              sx={{
                color: "#cbd5e1",
                fontSize: "0.8125rem",
                backgroundColor: "#0f1e38",
                borderRadius: "10px",
                "& fieldset": { borderColor: "rgba(255,255,255,0.08)" },
                "&:hover fieldset": { borderColor: "rgba(99,102,241,0.4)" },
                "&.Mui-focused fieldset": { borderColor: "#6366f1" },
                "& .MuiSvgIcon-root": { color: "#64748b" },
              }}
            >
              {months.map((m) => (
                <MenuItem key={m} value={m} sx={{ fontSize: "0.8125rem" }}>
                  {m}
                </MenuItem>
              ))}
            </Select>
          </FormControl>

          <Button
            size="small"
            variant="outlined"
            onClick={handleExportPDF}
            startIcon={<Download sx={{ fontSize: 16 }} />}
            sx={{
              borderColor: "rgba(255,255,255,0.1)",
              color: "#94a3b8",
              borderRadius: "10px",
              textTransform: "none",
              fontSize: "0.8125rem",
              px: 2,
              "&:hover": { borderColor: "#6366f1", color: "#c7d2fe", backgroundColor: "rgba(99,102,241,0.08)" },
            }}
          >
            Export
          </Button>
        </Box>
      </Box>

      {/* ── Summary Cards ───────────────────────────────────────────────── */}
      <Box sx={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 2, mb: 3 }}>
        {[
          {
            label: "Total Pembayaran",
            value: formatIDR(totalPembayaran),
            color: "#22c55e",
            icon: <ArrowUpward sx={{ fontSize: 16, color: "#22c55e" }} />,
            bg: "rgba(34,197,94,0.08)",
          },
          {
            label: "Total Bunga",
            value: formatIDR(totalBungaPenambahan),
            color: "#ef4444",
            icon: <ArrowDownward sx={{ fontSize: 16, color: "#ef4444" }} />,
            bg: "rgba(239,68,68,0.08)",
          },
          {
            label: "Penurunan Bersih Hutang",
            value: formatIDR(netReduction),
            color: netReduction >= 0 ? "#22c55e" : "#ef4444",
            icon: <SwapVert sx={{ fontSize: 16, color: netReduction >= 0 ? "#22c55e" : "#ef4444" }} />,
            bg: netReduction >= 0 ? "rgba(34,197,94,0.08)" : "rgba(239,68,68,0.08)",
          },
          {
            label: "Sisa Outstanding Akhir",
            value: formatIDR(finalOutstanding),
            color: "#f87171",
            icon: <CreditCard sx={{ fontSize: 16, color: "#f87171" }} />,
            bg: "rgba(248,113,113,0.1)",
          },
        ].map((c) => (
          <Paper
            key={c.label}
            elevation={0}
            sx={{
              p: 2.5,
              borderRadius: "14px",
              backgroundColor: "#0f1e38",
              border: "1px solid rgba(255,255,255,0.05)",
            }}
          >
            <Box sx={{ display: "flex", alignItems: "center", justifycontent: "space-between", mb: 1.5 }}>
              <Typography sx={{ fontSize: "0.7rem", color: "#64748b", fontWeight: 600, textTransform: "uppercase", letterSpacing: "0.06em" }}>
                {c.label}
              </Typography>
              <Box
                sx={{
                  width: 28,
                  height: 28,
                  borderRadius: "8px",
                  backgroundColor: c.bg,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  ml: "auto",
                }}
              >
                {c.icon}
              </Box>
            </Box>
            <Typography sx={{ fontSize: "1.25rem", fontWeight: 700, color: c.color }}>
              {c.value}
            </Typography>
          </Paper>
        ))}
      </Box>

      {/* ── Table ───────────────────────────────────────────────────────── */}
      <Paper
        elevation={0}
        sx={{
          borderRadius: "16px",
          backgroundColor: "#0f1e38",
          border: "1px solid rgba(255,255,255,0.05)",
          overflow: "hidden",
        }}
      >
        <Box
          sx={{
            px: 3,
            py: 2,
            borderBottom: "1px solid rgba(255,255,255,0.05)",
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
          }}
        >
          <Typography sx={{ fontWeight: 600, color: "#e2e8f0", fontSize: "0.9375rem" }}>
            Detail Perubahan Hutang — {selectedMonth}
          </Typography>
          <Typography sx={{ fontSize: "0.75rem", color: "#475569" }}>
            {rows.length} transaksi
          </Typography>
        </Box>

        <TableContainer>
          <Table size="small">
            <TableHead>
              <TableRow>
                {["Tanggal", "Keterangan", "Tipe", "Kategori", "Akun Liabilitas", "Nominal", "Sisa Outstanding"].map((h) => (
                  <TableCell key={h} sx={headCellSx}>{h}</TableCell>
                ))}
              </TableRow>
            </TableHead>
            <TableBody>
              {loading ? (
                <TableRow>
                  <TableCell colSpan={7} sx={{ ...cellSx, textAlign: "center", py: 4 }}>
                    Loading data...
                  </TableCell>
                </TableRow>
              ) : rows.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={7} sx={{ ...cellSx, textAlign: "center", py: 4, color: "#475569" }}>
                    Tidak ada perubahan liabilitas ditemukan.
                  </TableCell>
                </TableRow>
              ) : (
                rows.map((row, i) => (
                  <TableRow
                    key={i}
                    sx={{
                      backgroundColor: i % 2 === 0 ? "transparent" : "rgba(255,255,255,0.015)",
                      "&:hover": { backgroundColor: "rgba(248,113,113,0.06)" },
                      transition: "background-color 0.15s",
                    }}
                  >
                    <TableCell sx={{ ...cellSx, whiteSpace: "nowrap" }}>
                      {new Date(row.tanggal).toLocaleDateString("id-ID", {
                        day: "2-digit", month: "short", year: "numeric",
                      })}
                    </TableCell>
                    <TableCell sx={{ ...cellSx, color: "#e2e8f0", fontWeight: 500 }}>
                      {row.keterangan}
                    </TableCell>
                    <TableCell sx={cellSx}>
                      <Box sx={{ display: "flex", alignItems: "center", gap: 0.75 }}>
                        {row.tipe === "Pembayaran" ? (
                          <ArrowUpward sx={{ fontSize: 12, color: "#22c55e" }} />
                        ) : (
                          <ArrowDownward sx={{ fontSize: 12, color: "#ef4444" }} />
                        )}
                        <Typography
                          component="span"
                          sx={{
                            fontSize: "0.75rem",
                            fontWeight: 600,
                            color: row.tipe === "Pembayaran" ? "#22c55e" : "#ef4444",
                          }}
                        >
                          {row.tipe}
                        </Typography>
                      </Box>
                    </TableCell>
                    <TableCell sx={cellSx}>
                      <Chip
                        label={LIABILITY_CATEGORY_LABELS[row.kategori as LiabilityCategory] || row.kategori}
                        size="small"
                        variant="filled"
                        sx={{
                          fontSize: "0.6875rem",
                          height: 20,
                          fontWeight: 500,
                          borderRadius: "5px",
                          backgroundColor: "rgba(71,85,105,0.4)",
                          color: "#94a3b8",
                        }}
                      />
                    </TableCell>
                    <TableCell sx={{ ...cellSx, color: "#64748b" }}>
                      {row.metode}
                    </TableCell>
                    <TableCell
                      sx={{
                        ...cellSx,
                        textAlign: "right",
                        fontWeight: 700,
                        color: row.tipe === "Pembayaran" ? "#22c55e" : "#ef4444",
                        whiteSpace: "nowrap",
                      }}
                    >
                      {row.tipe === "Pembayaran" ? "−" : "+"}
                      {formatIDR(row.nominal)}
                    </TableCell>
                    <TableCell
                      sx={{
                        ...cellSx,
                        textAlign: "right",
                        fontWeight: 600,
                        color: "#f87171",
                        whiteSpace: "nowrap",
                        fontFamily: "monospace",
                      }}
                    >
                      {formatIDR(row.saldoOutstanding)}
                    </TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>
        </TableContainer>

        {/* Footer Summary */}
        <Divider sx={{ borderColor: "rgba(255,255,255,0.05)" }} />
        <Box
          sx={{
            px: 3,
            py: 2.5,
            display: "flex",
            alignItems: "center",
            justifyContent: "flex-end",
            gap: 4,
          }}
        >
          <Box sx={{ textAlign: "right" }}>
            <Typography sx={{ fontSize: "0.7rem", color: "#64748b", textTransform: "uppercase", letterSpacing: "0.06em", fontWeight: 600 }}>
              Total Pelunasan
            </Typography>
            <Typography sx={{ fontSize: "1rem", fontWeight: 700, color: "#22c55e" }}>
              {formatIDR(totalPembayaran)}
            </Typography>
          </Box>
          <Box sx={{ textAlign: "right" }}>
            <Typography sx={{ fontSize: "0.7rem", color: "#64748b", textTransform: "uppercase", letterSpacing: "0.06em", fontWeight: 600 }}>
              Total Bunga
            </Typography>
            <Typography sx={{ fontSize: "1rem", fontWeight: 700, color: "#ef4444" }}>
              {formatIDR(totalBungaPenambahan)}
            </Typography>
          </Box>
          <Box
            sx={{
              textAlign: "right",
              pl: 3,
              borderLeft: "1px solid rgba(255,255,255,0.08)",
            }}
          >
            <Typography sx={{ fontSize: "0.7rem", color: "#64748b", textTransform: "uppercase", letterSpacing: "0.06em", fontWeight: 600 }}>
              Sisa Outstanding Akhir
            </Typography>
            <Typography
              sx={{
                fontSize: "1.125rem",
                fontWeight: 800,
                color: "#f87171",
              }}
            >
              {formatIDR(finalOutstanding)}
            </Typography>
          </Box>
        </Box>
      </Paper>
    </Box>
  );
}
